"""Dev server for Jelly Tangle.

Serves the repo as static files (never cached, so edits show up on reload) and accepts one POST:
tools/levels.html sends the baked level table to /__bake and it is written to js/level-data.js.

    python tools/dev_server.py [port]        # default 5180, bound to 127.0.0.1 only

The game itself needs no server-side code: any static host works for playing.
"""
import http.server
import json
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUT = ROOT / "js" / "level-data.js"
HEADER = (
    "/* Baked levels: generated by tools/levels.html, do not edit by hand.\n"
    "   Each entry is one validated level (solvable, bot fail rate inside its band).\n"
    "   Format per worm: [colour, paint, dir, cells \"xyxy…\", layers, coveredBy, wrapped, dizzy]. */\n"
)


class Handler(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(ROOT), **kwargs)

    def end_headers(self):
        self.send_header("Cache-Control", "no-store")
        super().end_headers()

    def do_POST(self):
        if self.path != "/__bake":
            self.send_error(404)
            return
        size = int(self.headers.get("Content-Length", 0))
        if size <= 0 or size > 5_000_000:
            self.send_error(413)
            return
        try:
            levels = json.loads(self.rfile.read(size))["levels"]
            assert isinstance(levels, list) and levels
        except Exception:
            self.send_error(400)
            return
        rows = ",\n".join("  " + json.dumps(lv, separators=(",", ":"), ensure_ascii=False) for lv in levels)
        OUT.write_text(HEADER + "window.JT = window.JT || {};\nJT.LEVEL_DATA = [\n" + rows + "\n];\n", encoding="utf-8")
        body = json.dumps({"ok": True, "levels": len(levels), "file": str(OUT.relative_to(ROOT))}).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 5180
    with http.server.ThreadingHTTPServer(("127.0.0.1", port), Handler) as srv:
        print(f"Jelly Tangle dev server: http://localhost:{port}/")
        srv.serve_forever()
